import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../models/available_slot.dart';import '../../models/waiting_customer.dart';import '../../providers/auth_providers.dart';import '../../providers/dashboard_providers.dart';import '../../widgets/async_content.dart';import '../../widgets/page_header.dart';import '../../widgets/status_badge.dart';
class NotificationsScreen extends ConsumerWidget{const NotificationsScreen({super.key});String dt(DateTime d)=>'${d.month}/${d.day} ${d.hour.toString().padLeft(2,'0')}:${d.minute.toString().padLeft(2,'0')}';@override Widget build(BuildContext context,WidgetRef ref){final slots=ref.watch(slotsProvider),customers=ref.watch(waitingCustomersProvider);return SingleChildScrollView(padding:EdgeInsets.all(MediaQuery.sizeOf(context).width<600?16:32),child:Center(child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:1180),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const PageHeader(title:'LINE通知',subtitle:'条件に合うお客様へ空き枠をお知らせします（現在はモック送信）。'),const SizedBox(height:22),Text('通知候補',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:12),AsyncContent(value:slots,builder:(ss)=>AsyncContent(value:customers,builder:(cs){final open=ss.where((s)=>!s.isPast&&s.status==SlotStatus.open).toList();if(open.isEmpty)return const Card(child:Padding(padding:EdgeInsets.all(32),child:Center(child:Text('通知できる空き枠はありません。'))));return Column(children:open.map((s){final matches=ref.read(matchingServiceProvider).candidates(s,cs);return Padding(padding:const EdgeInsets.only(bottom:10),child:Card(child:ListTile(contentPadding:const EdgeInsets.all(18),title:Text('${dt(s.startAt)}〜${dt(s.endAt).split(' ').last}  ${s.menuName}',style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text('担当 ${s.staffName} ・ 通知候補 ${matches.length}名'),trailing:FilledButton.icon(onPressed:matches.isEmpty?null:()=>_notify(context,ref,s,matches),icon:const Icon(Icons.send_outlined),label:const Text('LINEで通知'))));}).toList());})),const SizedBox(height:28),Text('通知履歴',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:12),AsyncContent(value:ref.watch(notificationsProvider),builder:(items)=>items.isEmpty?const Card(child:Padding(padding:EdgeInsets.all(32),child:Center(child:Text('通知履歴はまだありません。')))):Column(children:items.map((n)=>Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.check)),title:Text(n.customerName),subtitle:Text('${dt(n.createdAt)} ・ ${n.message}'),trailing:const StatusBadge('モック送信',color:Colors.green)))).toList()))]))));}
Future<void> _notify(BuildContext context,WidgetRef ref,AvailableSlot slot,List<WaitingCustomer> matches)async{final selected=<String>{...matches.map((e)=>e.id)};final message=TextEditingController(text:'${slot.menuName}に空きが出ました。先着順でご予約いただけます。');final result=await showDialog<bool>(context:context,builder:(context)=>StatefulBuilder(builder:(context,set)=>AlertDialog(title:const Text('通知対象を選択'),content:SizedBox(width:520,child:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[...matches.map((c)=>CheckboxListTile(value:selected.contains(c.id),onChanged:(v)=>set(()=>v==true?selected.add(c.id):selected.remove(c.id)),title:Text(c.name),subtitle:Text(c.lineLinked?'LINE連携済み':'LINE未連携（モック）'))),const SizedBox(height:8),TextField(controller:message,maxLines:3,decoration:const InputDecoration(labelText:'通知メッセージ'))])),actions:[TextButton(onPressed:()=>Navigator.pop(context,false),child:const Text('キャンセル')),FilledButton(onPressed:selected.isEmpty?null:()=>Navigator.pop(context,true),child:Text('${selected.length}名にモック送信'))])));if(result==true){final id=ref.read(shopIdProvider).value;if(id!=null)await ref.read(dashboardRepositoryProvider).sendMockNotifications(id,slot,matches.where((c)=>selected.contains(c.id)).toList(),message.text);if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('モック通知を送信しました（LINE通信は行っていません）')));}message.dispose();}}
